// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.fullgc;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FullGcDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FullGcReporter reporter = new FullGcReporter();
        reporter.report("startup");

        // BOUNDED cache: evicts old entries, keeps Old gen healthy → few/no Full GCs.
        ReportCache bounded = new ReportCache(10_000); // max size
        for (int i = 0; i < 500_000; i++) {
            bounded.put("RPT-" + i, new byte[1024]); // 1KB report blobs
        }
        log.info(() -> "bounded cache holds " + bounded.size() + " entries (evicting)");
        reporter.report("after bounded cache");

        // BAD PATTERN: explicit System.gc() forces a Full GC on demand.
        log.warning(() -> "calling System.gc() — forces a Full GC (do NOT do this in prod)");
        System.gc();
        reporter.report("after explicit System.gc()");
    }
}

// ─── Would be in ReportCache.java (bounded via access-order LinkedHashMap) ───
class ReportCache {
    private final int maxSize;
    private final java.util.LinkedHashMap<String, byte[]> map;
    ReportCache(int maxSize) {
        this.maxSize = maxSize;
        this.map = new java.util.LinkedHashMap<>(16, 0.75f, true) {
            @Override protected boolean removeEldestEntry(java.util.Map.Entry<String, byte[]> e) {
                return size() > ReportCache.this.maxSize; // evict oldest → bound Old gen growth
            }
        };
    }
    void put(String k, byte[] v) { map.put(k, v); }
    int size() { return map.size(); }
}

// ─── Would be in FullGcReporter.java (counts Full GCs and total pause time) ───
class FullGcReporter {
    private static final Logger log = Logger.getLogger("BankLog");

    void report(String phase) {
        long fullCount = 0, fullMillis = 0;
        for (java.lang.management.GarbageCollectorMXBean gc :
                java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            String n = gc.getName();
            // Old-gen / Full collectors (names vary by collector).
            if (n.contains("Old") || n.contains("MarkSweep") || n.contains("G1 Old")
                    || n.contains("Global") || n.contains("Tenured")) {
                fullCount += gc.getCollectionCount();
                fullMillis += gc.getCollectionTime();
            }
        }
        long c = fullCount, m = fullMillis;
        log.info(() -> "[" + phase + "] Full GCs = " + c + ", total Full GC pause = " + m + " ms");
    }
}
